from pathlib import Path
import re, sys
missing=[]
refs=[]
for p in Path('.').rglob('*.md'):
    if '.git' in p.parts or 'build' in p.parts: continue
    text=p.read_text(errors='replace')
    for ref in sorted(set(re.findall(r'docs/[A-Za-z0-9_./-]+\.md', text))):
        refs.append((str(p),ref))
        if not Path(ref).exists(): missing.append((str(p),ref))
print('doc_refs=',len(refs))
for src,ref in refs: print(f'ref={src}->{ref}')
for src,ref in missing: print(f'MISSING={src}->{ref}')
if missing: sys.exit(1)
